public class ComposeDemo {
    static String composeService(String name, String image, int port) {
        return name + ":\n" +
               "  image: " + image + "\n" +
               "  ports: [\"" + port + ":" + port + "\"]";
    }
    public static void main(String[] args) {
        System.out.println(composeService("db", "postgres:16", 5432));
    }
}

