public class CiCdDemo {
    static void pipelineStages() {
        System.out.println("1. Source: code commit triggers pipeline");
        System.out.println("2. Build: compile and package the application");
        System.out.println("3. Test: run unit, integration, and security tests");
        System.out.println("4. Package: build Docker image and push to registry");
        System.out.println("5. Deploy: update running containers in target environment");
    }
    public static void main(String[] args) {
        pipelineStages();
    }
}
